from typing import List
import heapq
class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        m = len(conflictingPairs)
        byright = [[] for _ in range(n + 1)]
        for i, (a, b) in enumerate(conflictingPairs):
            if a > b: a, b = b, a
            byright[b].append((a, i))
        cnt = [0] * (n + 1)
        sole = [-1] * (n + 1)
        heap = []  # negative active a-values, one entry per distinct value
        gains = [0] * m
        base = 0
        for r in range(1, n + 1):
            for a, i in byright[r]:
                if cnt[a] == 0:
                    heapq.heappush(heap, -a)
                cnt[a] += 1
                if cnt[a] == 1:
                    sole[a] = i
                else:
                    sole[a] = -1
            while heap and cnt[-heap[0]] == 0:
                heapq.heappop(heap)
            top = -heap[0] if heap else 0
            base += r - top
            if top:
                top = heapq.heappop(heap)
                while heap and cnt[-heap[0]] == 0:
                    heapq.heappop(heap)
                second = -heap[0] if heap else 0
                heapq.heappush(heap, top)
                a = -top
                if cnt[a] == 1:
                    gains[sole[a]] += a - second
        return base + max(gains)

