import sys
input=sys.stdin.buffer.readline
INF=10**30

def main():
    N, M, Q = map(int, input().split())
    edges = []
    for _ in range(M):
        a, b, c = map(int, input().split())
        edges.append((a - 1, b - 1, c))

    queries = []
    closed = [False] * M
    for _ in range(Q):
        z = list(map(int, input().split()))
        if z[0] == 1:
            i = z[1] - 1
            closed[i] = True
            queries.append((1, i))
        else:
            queries.append((2, z[1] - 1, z[2] - 1))

    # Start from the graph after all closures, then reverse the operations.
    dist = [[INF] * N for _ in range(N)]
    for i in range(N):
        dist[i][i] = 0
    for i, (a, b, c) in enumerate(edges):
        if not closed[i]:
            dist[a][b] = dist[b][a] = c

    # APSP for the final graph.
    for k in range(N):
        dk = dist[k]
        for i in range(N):
            dik = dist[i][k]
            if dik == INF:
                continue
            di = dist[i]
            for j in range(N):
                candidate = dik + dk[j]
                if candidate < di[j]:
                    di[j] = candidate

    answers = [None] * Q
    for qi in range(Q - 1, -1, -1):
        query = queries[qi]
        if query[0] == 2:
            value = dist[query[1]][query[2]]
            answers[qi] = -1 if value == INF else value
        else:
            u, v, w = edges[query[1]]
            du = [dist[i][u] for i in range(N)]
            dv = [dist[i][v] for i in range(N)]
            # Insert one undirected edge. Symmetry lets us update only half
            # the matrix, setting both entries at once.
            for i in range(N):
                row = dist[i]
                iu = du[i] + w
                iv = dv[i] + w
                for j in range(i, N):
                    candidate1 = iu + dv[j]
                    candidate2 = iv + du[j]
                    candidate = candidate1 if candidate1 < candidate2 else candidate2
                    if candidate < row[j]:
                        dist[j][i] = row[j] = candidate

    sys.stdout.write("\n".join(map(str, (x for x in answers if x is not None))))

if __name__ == '__main__':
    main()

