import sys
import math

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, budget = data[0], data[1]
    processes = []
    idx = 2
    for _ in range(n):
        a, p, b, q = data[idx:idx + 4]
        idx += 4
        g = math.gcd(a, b)
        # Enumerate counts of the less cost-effective machine, which
        # need only range over one equal-capacity period.
        if p * b <= q * a:
            processes.append((a, p, b, q, a // g, True))
        else:
            processes.append((a, p, b, q, b // g, False))

    def feasible(capacity):
        total = 0
        for a, p, b, q, limit, enumerate_y in processes:
            best = 10**30
            if enumerate_y:
                for y in range(limit):
                    x = max(0, (capacity - b * y + a - 1) // a)
                    cost = x * p + y * q
                    if cost < best:
                        best = cost
            else:
                for x in range(limit):
                    y = max(0, (capacity - a * x + b - 1) // b)
                    cost = x * p + y * q
                    if cost < best:
                        best = cost
            total += best
            if total > budget:
                return False
        return True

    low, high = 0, 100 * budget + 1
    while high - low > 1:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid
    print(low)

if __name__ == '__main__':
    main()

