class Solution:
    def numberOfWays(self, n: int, x: int, y: int) -> int:
        mod = 10**9 + 7
        limit = min(n, x)
        dp = [0] * (limit + 1)
        dp[0] = 1

        for i in range(n):
            nxt = [0] * (limit + 1)
            for k in range(min(i, x) + 1):
                ways = dp[k]
                if ways == 0:
                    continue
                # Place the performer in one of the k already-used stages.
                nxt[k] = (nxt[k] + ways * k) % mod
                # Use a new stage, and choose its band's score.
                if k < x and k < limit:
                    nxt[k + 1] = (nxt[k + 1] + ways * (x - k) * y) % mod
            dp = nxt

        return sum(dp) % mod

