class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        m = len(s)
        eligible = []
        for t in range(1, m + 1):
            x = t
            steps = 0
            while x > 1:
                x = x.bit_count()
                steps += 1
            if steps + 1 <= k:
                eligible.append(t)
        ans = 0
        for t in eligible:
            used = 0
            ways = 0
            for i, bit in enumerate(s):
                if bit == '1':
                    rem = m - i - 1
                    need = t - used
                    if 0 <= need <= rem:
                        ways += comb(rem, need)
                    used += 1
            ans = (ans + ways) % MOD
        return ans

