import sys
from collections import deque

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    it = iter(data)
    n, m, q = next(it), next(it), next(it)
    cons = [(next(it)-1, next(it)-1) for _ in range(m)]
    queries = [(next(it)-1, next(it)-1) for _ in range(q)]
    out = []
    for l, r in queries:
        parent = list(range(n))
        size = [1] * n
        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x
        for i in range(l, r+1):
            a, b = cons[i]
            a, b = find(a), find(b)
            if a != b:
                if size[a] < size[b]: a, b = b, a
                parent[b] = a
                size[a] += size[b]
        roots = [find(x) for x in range(n)]
        ids = {}
        for x in roots:
            if x not in ids:
                ids[x] = len(ids)
        c = len(ids)
        adj = [set() for _ in range(c)]
        indeg = [0]*c
        bad = False
        for i in range(l, r+1):
            a,b = cons[i]
            a,b = roots[a], roots[b]
            # Ascending travel demands interior potential above endpoints;
            # descending travel demands it below endpoints.
            if cons[i][0] < cons[i][1]:
                u, v = ids[a], ids[b]
                lo, hi = cons[i][0]+1, cons[i][1]
                for x in range(lo, hi):
                    z = ids[roots[x]]
                    if z == u:
                        bad = True
                        break
                    if z not in adj[u]:
                        adj[u].add(z); indeg[z] += 1
            else:
                u, v = ids[a], ids[b]
                lo, hi = cons[i][1]+1, cons[i][0]
                for x in range(lo, hi):
                    z = ids[roots[x]]
                    if z == u:
                        bad = True
                        break
                    if z not in adj[z]:
                        adj[z].add(u); indeg[u] += 1
            if bad: break
        if not bad:
            dq = deque(i for i in range(c) if indeg[i] == 0)
            seen = 0
            while dq:
                u = dq.popleft(); seen += 1
                for v in adj[u]:
                    indeg[v] -= 1
                    if indeg[v] == 0: dq.append(v)
            bad = seen != c
        out.append('No' if bad else 'Yes')
    sys.stdout.write('\n'.join(out))

if __name__ == '__main__': main()

