import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    rows = [0] * n
    p = 2
    for _ in range(m):
        u, v = data[p] - 1, data[p + 1] - 1
        p += 2
        rows[u] |= 1 << v
        rows[v] |= 1 << u

    # Gauss-Jordan elimination over GF(2).
    pivot_cols = []
    r = 0
    for c in range(n):
        q = next((i for i in range(r, n) if (rows[i] >> c) & 1), None)
        if q is None:
            continue
        rows[r], rows[q] = rows[q], rows[r]
        for i in range(n):
            if i != r and ((rows[i] >> c) & 1):
                rows[i] ^= rows[r]
        pivot_cols.append(c)
        r += 1

    pivot_set = set(pivot_cols)
    free_cols = [c for c in range(n) if c not in pivot_set]
    values = [0] * n

    # Each nullspace basis vector occupies one bit of the vertex labels.
    for bit, c in enumerate(free_cols):
        vec = 1 << c
        for i, pivot in enumerate(pivot_cols):
            if (rows[i] & vec).bit_count() & 1:
                vec |= 1 << pivot
        for v in range(n):
            if (vec >> v) & 1:
                values[v] |= 1 << bit

    if any(x == 0 for x in values):
        print('No')
        return

    # Labels may be scaled by any common nonzero factor; this keeps the
    # output within the required 60-bit range.
    if n != 1 and max(values) < (1 << 58):
        values = [x << 2 for x in values]
    print('Yes')
    print(*values)

if __name__ == '__main__':
    main()

