import sys
import math

N = int(sys.stdin.buffer.readline())

# Any solution has d = x-y >= 1 and N = (y+d)^3-y^3 > d^3,
# so it suffices to try d up to floor(cuberoot(N)).
lo, hi = 0, 1
while hi ** 3 <= N:
    hi *= 2
while lo + 1 < hi:
    mid = (lo + hi) // 2
    if mid ** 3 <= N:
        lo = mid
    else:
        hi = mid

for d in range(1, lo + 1):
    if N % d:
        continue
    q = N // d
    # q = 3*y^2 + 3*d*y + d^2, hence
    # (6*y + 3*d)^2 = 12*q - 3*d^2.
    disc = 12 * q - 3 * d * d
    if disc < 0:
        continue
    root = math.isqrt(disc)
    if root * root == disc and root > 3 * d and (root - 3 * d) % 6 == 0:
        y = (root - 3 * d) // 6
        print(y + d, y)
        break
else:
    print(-1)

